def clean_existing_rows(apps, schema_editor):
    """PENDING accounts become ACTIVE; phone numbers are normalised to 8 digits
    and empty ones become NULL so the new unique constraint can be added."""
    User = apps.get_model("users", "User")
    User.objects.filter(account_status="PENDING").update(account_status="ACTIVE")
    seen = set()
    for user in User.objects.all():
        digits = "".join(ch for ch in (user.phone_number or "") if ch.isdigit())
        if digits.startswith("216") and len(digits) == 11:
            digits = digits[3:]
        user.phone_number = digits if len(digits) == 8 and digits not in seen else None
        if user.phone_number:
            seen.add(digits)
        user.save(update_fields=["phone_number"])


